# We enforce p<q and both perfect squares so that the unique valid solution 
# uses the positive root t = sqrt(p) + sqrt(q), yielding n = t^2 and total 3n.
# Also keep sizes reasonable.
while True:
    s = rng.randint(2, 20)   # sqrt(p)
    t = rng.randint(s+1, 35) # sqrt(q) > sqrt(p) ensures uniqueness
    p = s*s
    q = t*t
    n = (s + t)**2
    total = 3*n
    if total <= 20000:
        return {'p': p, 'q': q}

