# and d_{X->Y} equal to a common value d. Then p n^2 = n d^2, q n^2 = n (n-d)^2.
# With t = sqrt(n), these reduce to t^2 - 2 sqrt(p) t + (p - q) = 0, so t = sqrt(p) ± sqrt(q).
# Requiring t >= 0 and uniqueness is ensured by sqrt(p) < sqrt(q), forcing t = sqrt(p) + sqrt(q), hence n = (sqrt(p)+sqrt(q))^2.
p = assign.get('p', None)
q = assign.get('q', None)
if not isinstance(p, int) or not isinstance(q, int):
