import math
sp = int(math.isqrt(p))
sq = int(math.isqrt(q))
if sp*sp != p or sq*sq != q:
    # We require perfect squares so that degrees are integral and the intended unique solution applies
    return (False, None)
if not (sp < sq):
    # Enforce uniqueness: t = sqrt(p) - sqrt(q) would be nonnegative otherwise, giving a second solution
    return (False, None)
n = (sp + sq)**2
